def audience_class(viewer, owner, rel, card):
    if viewer == owner: return 'self'
    if rel.blocked_either_way: return 'blocked'
    if rel.friend: return 'friend'
    if rel.follower: return 'follower'
    return 'private_stranger' if card.account_private else 'public'

RANK = {'public':0,'followers':1,'friends':2,'self':3}
def visible_fields(settings, cls):
    if cls == 'blocked': return {}
    level = {'public':0,'private_stranger':-1,'follower':1,'friend':2,'self':3}[cls]
    return {k:v for k,(v,aud) in settings.items()
            if aud.startswith('list:') and cls=='self' or RANK.get(aud,99) <= level}
# custom lists evaluated separately by membership check, not cached per class

def erase(user):
    ledger.create(user, consumers=registry.all())
    stores.delete(user); vault.delete(user)
    stream.publish('UserErased', user)
    while not ledger.all_acked(user):
        for c in ledger.overdue(user): page_owner(c)
        sleep(1h)
    kms.schedule_key_deletion(dek_of(user), days=7)
    ledger.complete(user)
